contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable {
        require(amount > 0);
        // Fresh contract: recorded balance of this contract is 0.
        uint256 beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 contractBefore = address(c).balance;

        bool reverted;
        c.Collect(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 contractAfter = address(c).balance;

        // Since amount > recorded balance (>= MinSum check or amount check fails),
        // Collect must silently do nothing: no revert, no state or Ether change.
        assert(!reverted && afterBal == beforeBal && contractAfter == contractBefore);
    }

    receive() external payable {}
}

